<?php use App\Core\Csrf; use App\Core\View; ?>
<div class="page-head"><div><h1>刷题开放计划</h1><p>开放后，学生可在时间范围内反复练习，并自行选择顺序或随机模式。</p></div></div>
<section class="grid grid-2"><form class="card" method="post" action="/admin/practice-sets"><?= Csrf::field() ?><h2 class="section-title">创建开放计划</h2><div class="form-grid"><div class="field full"><label>练习名称</label><input name="title" required maxlength="180"></div><div class="field full"><label>说明</label><textarea name="description"></textarea></div><div class="field"><label>每次题量</label><input type="number" min="1" name="question_count" required value="10"></div><div class="field"><label>允许题型</label><div class="check-row"><label class="check"><input type="checkbox" name="allowed_types[]" value="single" checked>单选</label><label class="check"><input type="checkbox" name="allowed_types[]" value="multiple" checked>多选</label><label class="check"><input type="checkbox" name="allowed_types[]" value="judge" checked>判断</label><label class="check"><input type="checkbox" name="allowed_types[]" value="fill">填空</label></div></div><div class="field"><label>开放时间</label><input type="datetime-local" name="opens_at"></div><div class="field"><label>结束时间</label><input type="datetime-local" name="closes_at"></div><div class="field full"><label>标签筛选（可选）</label><input name="tags_filter"></div></div><div class="toolbar top-gap"><button class="btn btn-primary">保存计划</button></div></form><article class="card"><h2 class="section-title">当前题库容量</h2><?php foreach($counts as$c):?><div class="stat"><strong><?= (int)$c['c'] ?></strong><span><?= ['single'=>'单选题','multiple'=>'多选题','judge'=>'判断题','fill'=>'填空题'][$c['question_type']]??$c['question_type'] ?></span></div><?php endforeach;?><p class="callout">开放计划只规定题量与范围。学生每次开始练习时，系统才按其选择的“顺序”或“随机”模式生成题目快照。</p></article></section>
<section class="card"><h2 class="section-title">计划列表</h2><div class="table-wrap"><table><thead><tr><th>名称</th><th>状态</th><th>每次题量</th><th>题型</th><th>完成/总次数</th><th>开放时间</th><th>操作</th></tr></thead><tbody><?php foreach($sets as$s):?><tr><td><strong><?= View::e($s['title']) ?></strong><br><span class="muted"><?= View::e($s['tags_filter']?:'全部标签') ?></span></td><td><span class="status status-<?= View::e($s['status']) ?>"><?= View::e($s['status']) ?></span></td><td><?= (int)$s['question_count'] ?></td><td><?= View::e($s['allowed_types']) ?></td><td><?= (int)$s['completed_count'] ?> / <?= (int)$s['attempt_count'] ?></td><td><?= View::e($s['opens_at']??'立即') ?><br><?= View::e($s['closes_at']??'不限') ?></td><td><div class="toolbar"><?php foreach(['open'=>'开放','closed'=>'关闭','archived'=>'归档']as$value=>$label):?><form method="post" action="/admin/practice-sets/<?= $s['id'] ?>/status"><?= Csrf::field() ?><input type="hidden" name="status" value="<?= $value ?>"><button class="btn btn-sm <?= $value==='open'?'btn-success':'' ?>"><?= $label ?></button></form><?php endforeach;?></div></td></tr><?php endforeach;?></tbody></table></div></section>

